<?php
require_once __DIR__ . '/includes/functions.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
if(!$id){http_response_code(404);require '404.php';exit;}$s=db()->prepare('SELECT p.*,c.category_name,(SELECT AVG(rating) FROM reviews WHERE product_id=p.id AND status="approved") rating FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);require '404.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($p['stock']>0){$_SESSION['cart'][$id]=(int)($_SESSION['cart'][$id]??0)+1;flash('success','Phone added to cart.');}header('Location: cart.php');exit;}
$i=db()->prepare('SELECT image_path FROM product_images WHERE product_id=? ORDER BY id');$i->execute([$id]);$images=$i->fetchAll(PDO::FETCH_COLUMN)?:[null];$colors=colors_for($id);$r=db()->prepare('SELECT * FROM reviews WHERE product_id=? AND status="approved" ORDER BY created_at DESC');$r->execute([$id]);$reviews=$r->fetchAll();$page_title=$p['name'];require 'includes/header.php';
?><section class="section"><div class="container"><a class="back-link" href="index.php#shop">← Back to phones</a><div class="details-grid"><div class="gallery"><img id="main-image" src="<?=image_url($images[0])?>" alt="<?=e($p['name'])?>"><?php if(count($images)>1):?><div class="thumbnails"><?php foreach($images as $image):?><button type="button" data-image="<?=image_url($image)?>"><img src="<?=image_url($image)?>" alt="<?=e($p['name'])?>"></button><?php endforeach?></div><?php endif?></div><div><span class="badge <?=strtolower($p['brand'])?>"><?=e($p['brand'])?></span><h1 class="product-title"><?=e($p['name'])?></h1><div class="rating"><?= $p['rating'] ? number_format((float)$p['rating'],1).' / 5' : 'No reviews yet' ?></div><p class="price"><?=money($p['price'])?></p><p class="stock <?=$p['stock']>0?'in':'out'?>"><i class="fa-solid fa-circle"></i> <?=$p['stock']>0?$p['stock'].' available':'Currently out of stock'?></p><dl class="spec-list"><div><dt>Storage</dt><dd><?=e($p['storage'])?></dd></div><div><dt>Condition</dt><dd><?=e($p['condition'])?></dd></div><div><dt>Quality</dt><dd><?=e($p['quality'])?></dd></div><?php if($colors):?><div><dt>Colours</dt><dd><?=e(implode(', ',$colors))?></dd></div><?php endif?></dl><p><?=nl2br(e($p['description']))?></p><div class="details-actions"><?php if($p['stock']>0):?><form method="post" class="inline-cart"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="button primary"><i class="fa-solid fa-cart-plus"></i> Add to cart</button></form><?php endif?><a class="button whatsapp" target="_blank" rel="noopener" href="<?=e(whatsapp_url())?>"><i class="fa-brands fa-whatsapp"></i> Ask on WhatsApp</a></div></div></div><section class="specs"><h2>Technical specifications</h2><p><?=nl2br(e($p['specifications']?:'Contact us for full specifications.'))?></p></section><section class="reviews"><h2>Customer reviews</h2><?php foreach($reviews as $review):?><article><strong><?=e($review['customer_name'])?></strong><p><?=e($review['comment'])?></p></article><?php endforeach?><form class="review-form" method="post" action="reviews/submit-review.php"><h3>Leave a review</h3><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$id?>"><input required name="customer_name" maxlength="80" placeholder="Your name"><select required name="rating"><option value="">Your rating</option><?php for($x=5;$x>=1;$x--):?><option value="<?=$x?>"><?=$x?> stars</option><?php endfor?></select><textarea required name="comment" maxlength="1000" placeholder="Tell us about your experience"></textarea><button class="button primary">Submit review</button></form></section></div></section><?php require 'includes/footer.php'; ?>
